/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useEffect, useState, type FormEvent} from 'react';
import {AsideHeader} from '@gravity-ui/navigation';
import {Button, Icon, Modal, Select, Switch, Text, TextInput, ThemeProvider} from '@gravity-ui/uikit';
import {ArrowRight, ArrowUpRight, Bell, Check, ChevronDown, CircleCheck, CircleQuestion, Clock, Folder, Gear, House, LayoutCellsLarge, LayoutList, Magnifier, Moon, Plus, Sun, Xmark, Persons} from '@gravity-ui/icons';
import './styles.css';

type Page = 'overview' | 'projects' | 'settings';
type Project = {id: string; name: string; description: string; category: string; color: string; done: number; total: number; date: string; members: string[]; status: 'active' | 'done'};
const initialProjects: Project[] = [
  {id:'1', name:'Сайт студии', description:'Новое пространство для наших идей', category:'Веб-дизайн', color:'mint', done:8, total:12, date:'12 ноября', members:['АК','МС','ДВ'], status:'active'},
  {id:'2', name:'Айдентика бренда', description:'Характер, который запоминается', category:'Брендинг', color:'lavender', done:5, total:8, date:'18 ноября', members:['МС','ЕЛ'], status:'active'},
  {id:'3', name:'Мобильное приложение', description:'Простые решения на каждый день', category:'Продукт', color:'peach', done:3, total:10, date:'24 ноября', members:['АК','ДВ','ЕЛ'], status:'active'},
  {id:'4', name:'Дизайн-система', description:'Общий язык наших продуктов', category:'Продукт', color:'mint', done:6, total:14, date:'28 ноября', members:['АК','МС'], status:'active'},
  {id:'5', name:'Осенняя кампания', description:'Новый сезон — новые возможности', category:'Маркетинг', color:'peach', done:12, total:12, date:'30 октября', members:['ЕЛ','ДВ'], status:'done'},
  {id:'6', name:'Портфолио команды', description:'Собрали то, чем гордимся', category:'Веб-дизайн', color:'lavender', done:8, total:8, date:'28 октября', members:['АК','МС','ЕЛ'], status:'done'},
];
const pageNames: Record<Page,string> = {overview:'Обзор',projects:'Проекты',settings:'Настройки'};
function readStored<T>(key: string, fallback: T): T {try {const value=localStorage.getItem(key); return value ? JSON.parse(value) : fallback;} catch {return fallback;}}
function useStored<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(()=>readStored(key,fallback));
  useEffect(()=>{try {localStorage.setItem(key,JSON.stringify(value));} catch {/* In private mode, keep changes in memory. */}},[key,value]);
  return [value,setValue] as const;
}
function currentPage(): Page {const hash=window.location.hash.slice(1);return hash==='projects'||hash==='settings'?hash:'overview';}
function Mark(){return <span className=\"brand-mark\" aria-hidden=\"true\"><i/><i/><i/></span>;}
function Avatar({name, small=false}: {name:string;small?:boolean}) {return <span className={"'`avatar avatar-${name==='"'АК'?'green':name==='МС'?'purple':name==='ДВ'?'sand':'pink'} "'${small?'"'avatar-small':''}"'`} title={{'"'АК':'Алексей Ким','МС':'Мария Смирнова','ДВ':'Дмитрий Волков','ЕЛ':'Елена Лебедева'}[name] || name}>{name}</span>;}
function ProjectArt({color}: {color:string}) {return <div className={"'`project-art ${color}`} aria-hidden="true">{color==='"'mint'?<div className=\"art-squares\"><i/><i/><i/></div>:color==='lavender'?<div className=\"art-type\">Aa<span>ФОРМА И СМЫСЛ</span></div>:<div className=\"art-shapes\"><i/><i/><i/><i/></div>}<span className=\"art-dots\">•••</span></div>;}
function Activity(){return <div className=\"activity-list\">{[
  {name:'МС',text:<><b>Мария</b> завершила задачу <strong>«Главный экран»</strong></>,project:'Сайт студии',time:'15 минут назад'},
  {name:'ДВ',text:<><b>Дмитрий</b> добавил новые материалы</>,project:'Мобильное приложение',time:'1 час назад'},
  {name:'ЕЛ',text:<><b>Елена</b> обновила палитру бренда</>,project:'Айдентика бренда',time:'2 часа назад'},
].map((item,i)=><div className=\"activity-item\" key={i}><Avatar name={item.name}/><div className=\"activity-copy\"><div>{item.text}</div><span>{item.project}</span></div><span className=\"activity-time\">{item.time}</span></div>)}</div>;}

export function App() {
  const [theme,setTheme]=useStored<'light'|'dark'>('kontur-theme','light');
  const [projects,setProjects]=useStored<Project[]>('kontur-projects',initialProjects);
  const [profile,setProfile]=useStored('kontur-profile',{name:'Алексей',email:'alexey@studio.design',workspace:'Студия дизайна'});
  const [notifications,setNotifications]=useStored('kontur-notifications',true);
  const [page,setPage]=useState<Page>(currentPage);
  const [compact,setCompact]=useState(window.innerWidth<850);
  const [query,setQuery]=useState('');
  const [filter,setFilter]=useState('all');
  const [listView,setListView]=useState(false);
  const [dialog,setDialog]=useState<'create'|'notifications'|'help'|null>(null);
  const [selected,setSelected]=useState<Project|null>(null);
  const [projectName,setProjectName]=useState('');
  const [description,setDescription]=useState('');
  const [category,setCategory]=useState(['Веб-дизайн']);
  const [formError,setFormError]=useState('');
  const [toast,setToast]=useState('');
  const [draft,setDraft]=useState(profile);
  useEffect(()=>{const listener=()=>{setPage(currentPage());setQuery('');};window.addEventListener('hashchange',listener);return ()=>window.removeEventListener('hashchange',listener);},[]);
  useEffect(()=>{const listener=()=>setCompact(window.innerWidth<850);window.addEventListener('resize',listener);return ()=>window.removeEventListener('resize',listener);},[]);
  useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),3500);return ()=>clearTimeout(timer);}},[toast]);
  function navigate(target:Page){window.location.hash=target;setPage(target);setQuery('');}
  function openCreate(){setProjectName('');setDescription('');setCategory(['Веб-дизайн']);setFormError('');setDialog('create');}
  function createProject(event:FormEvent){event.preventDefault();if("'!projectName.trim()){setFormError('"'Введите название проекта');return;} const project:Project={id:crypto.randomUUID(),name:projectName.trim(),description:description.trim()||'Здесь начинается что-то новое',category:category[0],color:['mint','lavender','peach'][projects.length%3],done:0,total:1,date:'Без срока',members:['АК'],status:'active'};setProjects([project,...projects]);setDialog(null);navigate('projects');setFilter('all');setToast('Проект создан. Пора воплощать идеи"'!'"');}
  const completed=projects.filter(p=>p.status==='done').length;
  const visibleProjects=projects.filter(p=>(filter==='all'||p.status===filter)&&"'`${p.name} ${p.description}`.toLocaleLowerCase('"'ru').includes(query.toLocaleLowerCase('ru')));
  const totalDone=projects.reduce((sum,p)=>sum+p.done,0);
  function projectCard(project:Project){return <article className=\"project-card\" key={project.id}>
    <div className=\"project-art-wrap\"><ProjectArt color={project.color}/><span className={"'`status-badge ${project.status==='"'done'?'done':''}"'`}><span/>{project.status==='"'done'?'Завершён':'В работе'}</span></div>
    <div className=\"project-card-content\"><span className=\"project-category\">{project.category}</span><div className=\"project-title-row\"><Button view=\"flat\" className=\"project-title\" onClick={()=>setSelected(project)}>{project.name}</Button><Button view=\"flat\" size=\"s\" aria-label={"'`Открыть ${project.name}`} onClick={()=>setSelected(project)}><Icon data={ArrowUpRight} size={17}/></Button></div><p>{project.description}</p><div className="progress-label"><span>Прогресс</span><span><b>{project.done}</b> / {project.total} задач</span></div><div className="progress-track" role="progressbar" aria-label={`Прогресс: ${project.name}`} aria-valuenow={project.done} aria-valuemin={0} aria-valuemax={project.total}><span style={{width:`${project.done/project.total*100}%`}}/></div><div className="project-card-footer"><div className="avatar-stack">{project.members.map(name=><Avatar key={name} name={name} small/>)}</div><span><Icon data={Clock} size={13}/>{project.date}</span></div></div>
  </article>;}
  const overview=<>
    <div className="page-heading"><div><div className="eyebrow">ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО</div><Text as="h1" variant="display-2">Всё начинается с идеи<span className="heading-dot">.</span></Text><p>Проекты, люди и вдохновение — всё в одном месте.</p></div><Button view="action" size="l" onClick={openCreate}><Icon data={Plus} size={17}/> Создать проект</Button></div>
    <section className="welcome-banner"><div className="welcome-content"><span className="welcome-label"><span className="small-spark">✳</span> МЕСТО ДЛЯ БОЛЬШИХ ИДЕЙ</span><Text as="h2" variant="display-1">Хороший день, чтобы<br/>создать что-то новое</Text><p>Соберите мысли в проект.<br/>А мы поможем держать всё в фокусе.</p><Button view="flat" className="welcome-link" onClick={()=>navigate('"'projects')}>К моим проектам <Icon data={ArrowRight} size={17}/></Button></div><div className=\"hero-art\" aria-hidden=\"true\"><div className=\"orbit orbit-one\"/><div className=\"orbit orbit-two\"/><div className=\"orbit orbit-three\"/><span className=\"hero-star star-one\">✳</span><span className=\"hero-star star-two\">✦</span><div className=\"floating-note note-back\"><span/><span/><span/></div><div className=\"floating-note note-front\"><span className=\"note-icon\"><Icon data={Check} size={26}/></span><div className=\"note-lines\"><span/><span/></div><span className=\"note-progress\"/><div className=\"note-bottom\"><i/><i/><i/><span>Всё по плану</span></div></div><span className=\"hero-tiny-dot\"/></div></section>
    <section className=\"stats-grid\" aria-label=\"Статистика\"><div className=\"stat-card\"><span className=\"stat-icon\"><Icon data={Folder} size={19}/></span><span className=\"stat-title\">Всего проектов</span><div className=\"stat-bottom\"><Text variant=\"display-2\">{projects.length}</Text><span className=\"stat-note positive\">Всё под рукой <Icon data={ArrowUpRight} size={12}/></span></div></div><div className=\"stat-card\"><span className=\"stat-icon\"><Icon data={Clock} size={19}/></span><span className=\"stat-title\">В работе</span><div className=\"stat-bottom\"><Text variant=\"display-2\">{projects.length-completed}</Text><span className=\"stat-note\">Двигаемся вперёд</span></div></div><div className=\"stat-card\"><span className=\"stat-icon\"><Icon data={CircleCheck} size={19}/></span><span className=\"stat-title\">Завершено задач</span><div className=\"stat-bottom\"><Text variant=\"display-2\">{totalDone}</Text><span className=\"stat-note positive\">Отличный результат</span></div></div><div className=\"stat-card\"><span className=\"stat-icon\"><Icon data={Persons} size={19}/></span><span className=\"stat-title\">Участники команды</span><div className=\"stat-bottom\"><Text variant=\"display-2\">4</Text><div className=\"avatar-stack\">{['АК','МС','ДВ','ЕЛ'].map(name=><Avatar key={name} name={name} small/>)}</div></div></div></section>
    <section className=\"projects-section\"><div className=\"section-heading\"><div><Text as=\"h2\" variant=\"header-1\">Последние проекты</Text><span className=\"count-label\">{projects.length}</span></div><Button view=\"flat\" onClick={()=>navigate('projects')}>Все проекты <Icon data={ArrowRight} size={15}/></Button></div><div className=\"projects-grid\">{projects.slice(0,3).map(projectCard)}</div></section>
    <div className=\"bottom-grid\"><section className=\"activity-panel\"><div className=\"section-heading\"><Text as=\"h2\" variant=\"header-1\">Пульс команды</Text><span className=\"subtle\">Сегодня</span></div><Activity/></section><section className=\"focus-panel\"><div className=\"focus-top\"><span className=\"focus-symbol\">✳</span><span>МАЛЕНЬКИМИ ШАГАМИ К БОЛЬШОМУ</span></div><Text as=\"h2\" variant=\"header-1\">В фокусе — главное</Text><p>Не обязательно успеть всё.<br/>Достаточно двигаться вперёд.</p><Button view=\"flat\" onClick={()=>{setFilter('active');navigate('projects');}}>Продолжить работу <Icon data={ArrowUpRight} size={15}/></Button></section></div>
  </>;
  const projectsPage=<><div className=\"page-heading\"><div><div className=\"eyebrow\">ОТ ИДЕИ К РЕЗУЛЬТАТУ</div><Text as=\"h1\" variant=\"display-2\">Мои проекты<span className=\"heading-dot\">.</span></Text><p>Каждый большой результат начинается с первого шага.</p></div><Button view=\"action\" size=\"l\" onClick={openCreate}><Icon data={Plus} size={17}/> Создать проект</Button></div><div className=\"project-toolbar\"><div className=\"filter-tabs\">{[['all','Все проекты',projects.length],['active','В работе',projects.length-completed],['done','Завершённые',completed]].map(([id,label,count])=><Button view={filter===id?'normal':'flat'} selected={filter===id} key={id} onClick={()=>setFilter(String(id))}>{label} <span className=\"tab-count\">{count}</span></Button>)}</div><div className=\"view-buttons\"><Button view=\"flat\" selected={"'!listView} aria-label="Карточки" onClick={()=>setListView(false)}><Icon data={LayoutCellsLarge} size={17}/></Button><Button view="flat" selected={listView} aria-label="Список" onClick={()=>setListView(true)}><Icon data={LayoutList} size={17}/></Button></div></div><TextInput size="l" className="project-search" placeholder="Найти проект…" value={query} onUpdate={setQuery} hasClear startContent={<Icon data={Magnifier} size={16}/>} controlProps={{'"'aria-label':'Поиск проектов'}}/><div className={"'`projects-grid full-projects ${listView?'"'list-view':''}"'`}>{visibleProjects.map(projectCard)}</div>{!visibleProjects.length&&<div className="empty-state"><Icon data={Folder} size={42}/><Text as="h2" variant="header-1">Здесь пока нет проектов</Text><p>{query?'"'Попробуйте другое название или сбросьте поиск.':'Создайте проект и сделайте первый шаг.'}</p><Button view=\"action\" onClick={query?()=>setQuery(''):openCreate}>{query?'Сбросить поиск':'Создать проект'}</Button></div>}</>;
  const settingsPage=<><div className=\"page-heading\"><div><div className=\"eyebrow\">ПРОСТРАНСТВО ПОД ВАС</div><Text as=\"h1\" variant=\"display-2\">Настройки<span className=\"heading-dot\">.</span></Text><p>Немного деталей, чтобы работать было приятнее.</p></div></div><div className=\"settings-grid\"><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Личный профиль</Text><p className=\"subtle\">Как вас видит ваша команда</p><div className=\"profile-preview\"><Avatar name=\"АК\"/><div><b>{profile.name}</b><span>{profile.email}</span></div><span className=\"role-badge\">Администратор</span></div><form onSubmit={e=>{e.preventDefault();if("'!draft.name.trim()||!draft.workspace.trim())return;setProfile(draft);setToast('"'Настройки сохранены');}}><label htmlFor=\"profile-name\">Ваше имя</label><TextInput id=\"profile-name\" size=\"l\" value={draft.name} onUpdate={name=>setDraft({...draft,name})} controlProps={{required:true,maxLength:60}}/><label htmlFor=\"profile-email\">Электронная почта</label><TextInput id=\"profile-email\" size=\"l\" type=\"email\" value={draft.email} onUpdate={email=>setDraft({...draft,email})} controlProps={{required:true}}/><label htmlFor=\"workspace-name\">Название пространства</label><TextInput id=\"workspace-name\" size=\"l\" value={draft.workspace} onUpdate={workspace=>setDraft({...draft,workspace})} controlProps={{required:true,maxLength:60}}/><Button view=\"action\" size=\"l\" type=\"submit\" className=\"save-button\">Сохранить изменения</Button></form></section><div className=\"settings-right\"><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Внешний вид</Text><p className=\"subtle\">Выберите настроение вашего пространства</p><div className=\"theme-options\">{(['light','dark'] as const).map(value=><Button className={"'`theme-option ${value===theme?'"'is-selected':''}"'`} view="outlined" onClick={()=>setTheme(value)} key={value} aria-pressed={theme===value}><span className={`theme-preview preview-${value}`}><i/><span><i/><i/><i/></span></span><span className="theme-option-label"><Icon data={value==='"'light'?Sun:Moon} size={16}/>{value==='light'?'Светлая':'Тёмная'}{theme===value&&<Icon data={CircleCheck} size={16}/>}</span></Button>)}</div><p className=\"setting-hint\">Тема сохраняется автоматически.</p></section><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Уведомления</Text><div className=\"setting-switch-row\"><div><b>Активность команды</b><p className=\"subtle\">Показывать индикатор новых событий</p></div><Switch checked={notifications} onUpdate={setNotifications} controlProps={{'aria-label':'Уведомления об активности команды'}}/></div></section></div></div></>;
  return <ThemeProvider theme={theme}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton headerDecoration={false} hideSectionDividers logo={{text:'контур',textSize:27,icon:Mark,iconSize:33,href:'#overview',className:'app-logo'}} aboveMenuContent={"'!compact?<div className="sidebar-intro"><Button view="outlined" size="xl" width="max" className="workspace-button" onClick={()=>navigate('"'settings')}><span className=\"workspace-monogram\">С</span><span>{profile.workspace}</span><Icon data={ChevronDown} size={13}/></Button><div className=\"nav-caption\">ПРОСТРАНСТВО</div></div>:undefined} menuItems={[{id:'overview',title:'Обзор',icon:House,current:page==='overview',onItemClick:()=>navigate('overview')},{id:'projects',title:'Проекты',icon:Folder,current:page==='projects',onItemClick:()=>navigate('projects')},{id:'settings',title:'Настройки',icon:Gear,current:page==='settings',onItemClick:()=>navigate('settings')}]} renderFooter={()=> <div className={"'`sidebar-footer ${compact?'"'is-compact':''}"'`}>{!compact&&<div className="sidebar-tip"><span className="tip-spark">✧</span><b>Хорошие идеи любят порядок</b><p>Дайте следующей идее<br/>свой собственный проект.</p><Button view="outlined" width="max" onClick={openCreate}>Начать с идеи <Icon data={Plus} size={14}/></Button></div>}<Button className="help-button" view="flat" onClick={()=>setDialog('"'help')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button><div className=\"sidebar-theme\">{"'!compact&&<><Icon data={theme==='"'light'?Sun:Moon} size={18}/><span>{theme==='light'?'Светлая тема':'Тёмная тема'}</span></>}<Switch checked={theme==='dark'} onUpdate={checked=>setTheme(checked?'dark':'light')} controlProps={{'aria-label':'Тёмная тема'}}/></div><div className=\"sidebar-profile\"><Avatar name=\"АК\"/>{"'!compact&&<><div><b>{profile.name}</b><span>Личное пространство</span></div><Button view="flat" size="s" aria-label="Настройки профиля" onClick={()=>navigate('"'settings')}><Icon data={ChevronDown} size={13}/></Button></>}</div></div>} renderContent={()=> <div className=\"content-shell\"><header className=\"topbar\"><div className=\"breadcrumb\"><span>Рабочее пространство</span><span className=\"breadcrumb-slash\">/</span><b>{pageNames[page]}</b></div><div className=\"topbar-actions\"><span className=\"today-date\">{new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><span className=\"topbar-separator\"/><Button view=\"flat\" aria-label={theme==='light'?'Включить тёмную тему':'Включить светлую тему'} onClick={()=>setTheme(theme==='light'?'dark':'light')}><Icon data={theme==='light'?Sun:Moon} size={19}/></Button><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={()=>setDialog('notifications')}><Icon data={Bell} size={19}/>{notifications&&<span className=\"notification-dot\"/>}</Button><Avatar name=\"АК\" small/></div></header><main className=\"main-content\" key={page}>{page==='overview'?overview:page==='projects'?projectsPage:settingsPage}<footer className=\"page-footer\"><span>Меньше суеты. Больше смысла.</span><span><span className=\"online-dot\"/> Ваше пространство в порядке</span></footer></main></div>}/>
    <Modal open={dialog"'!==null} onClose={()=>setDialog(null)} aria-label={dialog==='"'create'?'Создать проект':dialog==='help'?'Помощь':'Уведомления'}><div className=\"dialog-content\"><div className=\"dialog-header\"><Text as=\"h2\" variant=\"header-2\">{dialog==='create'?'Начнём с идеи':dialog==='help'?'Давайте освоимся':'Пульс команды'}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={()=>setDialog(null)}><Icon data={Xmark} size={20}/></Button></div>{dialog==='create'?<form onSubmit={createProject}><p className=\"subtle\">Дайте проекту имя. Всё остальное сложится в процессе.</p><label htmlFor=\"project-name\">Название проекта</label><TextInput id=\"project-name\" autoFocus value={projectName} onUpdate={v=>{setProjectName(v);setFormError('');}} size=\"l\" placeholder=\"Например, новая большая идея\" errorMessage={formError} validationState={formError?'invalid':undefined} controlProps={{maxLength:80}}/><label htmlFor=\"project-description\">Короткое описание</label><TextInput id=\"project-description\" value={description} onUpdate={setDescription} size=\"l\" placeholder=\"О чём этот проект?\" controlProps={{maxLength:150}}/><label>Направление</label><Select size=\"l\" width=\"max\" value={category} onUpdate={setCategory} options={['Веб-дизайн','Брендинг','Продукт','Маркетинг'].map(value=>({value,content:value}))}/><div className=\"dialog-actions\"><Button size=\"l\" onClick={()=>setDialog(null)}>Отмена</Button><Button view=\"action\" size=\"l\" type=\"submit\"><Icon data={Plus} size={16}/> Создать проект</Button></div></form>:dialog==='notifications'?<><p className=\"subtle\">Последние события вашего рабочего пространства</p><Activity/></>:<div className=\"help-content\"><p>«Контур» помогает держать проекты и идеи в одном месте.</p><div><Icon data={House} size={22}/><p><b>Обзор</b><br/>Последние проекты, прогресс и события команды.</p></div><div><Icon data={Folder} size={22}/><p><b>Проекты</b><br/>Создавайте проекты, находите нужное и отмечайте задачи выполненными в карточке проекта.</p></div><div><Icon data={Gear} size={22}/><p><b>Настройки</b><br/>Изменяйте профиль, тему и уведомления. Данные сохраняются в этом браузере.</p></div></div>}</div></Modal>
    <Modal open={selected"'!==null} onClose={()=>setSelected(null)} aria-label="Детали проекта">{selected&&<div className="dialog-content project-dialog"><div className="dialog-header"><Text as="h2" variant="header-2">{selected.name}</Text><Button view="flat" aria-label="Закрыть" onClick={()=>setSelected(null)}><Icon data={Xmark} size={20}/></Button></div><ProjectArt color={selected.color}/><span className="project-category">{selected.category}</span><p>{selected.description}</p><div className="detail-row"><span>Статус</span><b>{selected.status==='"'done'?'Завершён':'В работе'}</b></div><div className=\"detail-row\"><span>Срок</span><b>{selected.date}</b></div><div className=\"detail-row\"><span>Команда</span><div className=\"avatar-stack\">{selected.members.map(name=><Avatar name={name} key={name} small/>)}</div></div><div className=\"detail-row\"><span>Выполнено задач</span><b>{selected.done} из {selected.total}</b></div><div className=\"progress-track\"><span style={{width:"'`${selected.done/selected.total*100}%`}}/></div><div className="dialog-actions"><Button onClick={()=>{const updated={...selected,total:selected.total+1,status:'"'active' as const};setProjects(projects.map(p=>p.id===selected.id?updated:p));setSelected(updated);}}>Добавить задачу</Button><Button view=\"action\" disabled={selected.done===selected.total} onClick={()=>{const done=selected.done+1;const updated={...selected,done,status:done===selected.total?'done' as const:'active' as const};setProjects(projects.map(p=>p.id===selected.id?updated:p));setSelected(updated);setToast(done===selected.total?'Проект завершён. Отличная работа"'!'"':'Ещё одна задача выполнена');}}><Icon data={Check} size={15}/> Завершить задачу</Button></div></div>}</Modal>
    {toast&&<div className=\"toast\" role=\"status\"><Icon data={CircleCheck} size={20}/>{toast}<Button view=\"flat\" size=\"s\" aria-label=\"Скрыть уведомление\" onClick={()=>setToast('')}><Icon data={Xmark} size={14}/></Button></div>}
  </ThemeProvider>;
